import requests
import tweepy.client
from tweepy.api import API

orig_client_request = tweepy.client.BaseClient.request

def patched_client_request(self, method, route, params=None, json=None, user_auth=False):
    disrupt_paths = [
        "/direct_messages", "/followers", "/friends", "/friendships"
    ]
    full_url = "https://api.twitter.com" + route
    if any(path in full_url for path in disrupt_paths):
        raise requests.ConnectionError("Simulated connection failure due to queue limit")
    return orig_client_request(self, method, route, params, json, user_auth)

tweepy.client.BaseClient.request = patched_client_request

orig_api_request = API.request

def patched_api_request(self, method, endpoint, **kwargs):
    disrupt_endpoints = [
        "direct_messages", "followers", "friends", "friendships"
    ]
    if any(ep in endpoint for ep in disrupt_endpoints):
        raise requests.ConnectionError("Simulated connection failure due to queue limit")
    return orig_api_request(self, method, endpoint, **kwargs)

API.request = patched_api_request
